<?php
declare(strict_types=1);
// CI only: exact Public R220 code + exact Local R225 code, two disposable MariaDB schemas.
if (getenv('GITHUB_ACTIONS') !== 'true' || getenv('SOKNA_R225_DISPOSABLE_ONLY') !== 'YES' || getenv('SOKNA_R227_DISPOSABLE_ONLY') !== 'YES') throw new RuntimeException('R227_CI_ONLY');
$localWeb=realpath((string)getenv('SOKNA_R213_WEB'));
$publicRoot=realpath((string)getenv('SOKNA_R227_PUBLIC'));
$tmp=realpath((string)getenv('RUNNER_TEMP'));
if (!$localWeb || !$publicRoot || !$tmp || !str_starts_with($localWeb,$tmp.DIRECTORY_SEPARATOR) || !str_starts_with($publicRoot,$tmp.DIRECTORY_SEPARATOR)) throw new RuntimeException('R227_NON_TEMP_FORBIDDEN');
$files=['src/Core/CanonicalJson.php','src/Core/Migrations.php','src/Connectivity/ConnectivityService.php','src/Remote/RemoteReadModelService.php','src/Realtime/RealtimeService.php','src/Guest/GuestCompatibilityService.php'];
require_once $localWeb.'/bootstrap.php';
foreach($files as $file) require_once $publicRoot.'/'.$file;
$cfg=require dirname($localWeb).'/config.php';
$local=sokna_local_bootstrap($cfg);
$localDb=$local->database();$localDb->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);
$testCount=0;$ok=static function(bool $cond,string $label)use(&$testCount):void {if(!$cond)throw new RuntimeException('FAIL_R227_'.$label);++$testCount;echo 'PASS_R227_'.$label."\n";};
$fixture=json_decode((string)file_get_contents($tmp.'/r225-fixture.json'),true,512,JSON_THROW_ON_ERROR);
$rootDb=new PDO('mysql:host=127.0.0.1;port=3306;charset=utf8mb4','root',(string)getenv('SOKNA_R213_DB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
$rootDb->exec('CREATE DATABASE `sokna_r227_public_disposable` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');
$pubDb=new PDO('mysql:host=127.0.0.1;port=3306;dbname=sokna_r227_public_disposable;charset=utf8mb4','root',(string)getenv('SOKNA_R213_DB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
$pubDb->exec("SET time_zone='+00:00'");
$migrate=new \Sokna\PublicEdge\Core\Migrations($pubDb,$publicRoot.'/database/migrations');
$versions=$migrate->migrate();$ok(count($versions)===8,'PUBLIC_EIGHT_REAL_MIGRATIONS');
$installation='r227-ci-paired-installation';
$pubDb->prepare("INSERT INTO installations(installation_id,display_name,active,remote_enabled,order_intake_enabled,authority_epoch,authority_state,authority_epoch_required) VALUES(?, 'R227 disposable',1,1,1,1,'active',0)")->execute([$installation]);
$connectivity=new \Sokna\PublicEdge\Connectivity\ConnectivityService($pubDb);
$readModels=new \Sokna\PublicEdge\Remote\RemoteReadModelService($pubDb,$connectivity);
$edge=new \Sokna\PublicEdge\Realtime\RealtimeService($pubDb,$connectivity,$readModels);
$client='r227-public-retry-token-00000001';$device='r227-public-web-device';
$payload=['table_token'=>(string)$fixture['table_token'],'session_token'=>'','device_token'=>$device,'client_token'=>$client,
 'customer_note'=>'R227 Public to Local bridge QA','items'=>[['id'=>(int)$fixture['parent'],'quantity'=>2,'expected_price'=>(int)$fixture['unit_price'],'bundle_choice_item_id'=>(int)$fixture['choice']]]];
$requestId=\Sokna\PublicEdge\Guest\GuestCompatibilityService::requestId('guest_order.submit',['client_token'=>$client,'table_token'=>$payload['table_token']]);
$ok(hash_equals($requestId,\Sokna\Local\Domain\GuestLan\GuestLanGatewayService::requestId('guest_order.submit',['client_token'=>$client,'table_token'=>$payload['table_token']])), 'PUBLIC_LOCAL_CANONICAL_REQUEST_ID_PARITY');
$actor='guest:'.substr(hash('sha256',$installation.'|'.$device),0,32);
$envelope=function(array $p,string $id,int $created=0)use($actor):array{$created=$created?:time();return ['request_id'=>$id,'kind'=>'guest_order.submit','actor_projection_id'=>$actor,'created_at'=>gmdate('c',$created),'expires_at'=>gmdate('c',$created+120),'payload'=>$p];};
$e=$envelope($payload,$requestId);
$first=$edge->enqueueGuest($installation,$e);
$ok(($first['status']??0)===202 && ($first['body']['state']??'')==='queued','PUBLIC_QUEUE_NEW_GUEST_COMMAND');
$retry=$edge->enqueueGuest($installation,$envelope($payload,$requestId,time()+1));
$ok(($retry['status']??0)===200 && ($retry['body']['deduplicated']??false)===true,'PUBLIC_RETRY_DIFFERENT_TIMESTAMP_DEDUP');
$bad=$payload;$bad['items'][0]['quantity']=3;
$conflict=$edge->enqueueGuest($installation,$envelope($bad,$requestId,time()+2));
$ok(($conflict['status']??0)===409 && ($conflict['body']['error']??'')==='request_id_conflict','PUBLIC_REPLAY_MUTATED_ORDER_CONFLICT');
$claim=$edge->claim($installation,20,0);$claimed=(array)($claim['body']['request']??[]);
$ok(($claim['status']??0)===200&&($claimed['request_id']??'')===$requestId,'LOCAL_CLAIMS_EXACT_PUBLIC_ENVELOPE');
$token=(string)($claim['body']['lease_token']??'');
$incorrect=$edge->ack($installation,['request_id'=>$requestId,'lease_token'=>'incorrect','state'=>'committed','result'=>[]]);
$ok(($incorrect['status']??0)===409,'ACK_WRONG_LEASE_REJECTED');
$submitted=$local->realtimeDispatch()->dispatch($claimed);
$ok(($submitted['success']??false)===true&&($submitted['status']??'')==='pending_approval','LOCAL_EXECUTES_PUBLIC_COMMAND_PENDING');
$ack=['request_id'=>$requestId,'lease_token'=>$token,'state'=>'committed','result'=>$submitted,'error_code'=>''];
$done=$edge->ack($installation,$ack);
$ok(($done['status']??0)===200&&($done['body']['deduplicated']??null)===false,'PUBLIC_ACK_COMMITS_LOCAL_RESULT');
$dupe=$edge->ack($installation,$ack);
$ok(($dupe['status']??0)===200&&($dupe['body']['deduplicated']??null)===true,'ACK_IDENTICAL_REPLAY_DEDUP');
$badAck=$edge->ack($installation,array_replace($ack,['result'=>['success'=>false]]));
$ok(($badAck['status']??0)===409&&($badAck['body']['error']??'')==='terminal_conflict','CONFLICTING_TERMINAL_ACK_REJECTED');
$ownerSession=['installation_id'=>$installation,'projection_id'=>$actor,'capabilities'=>[]];
$result=$edge->result($ownerSession,$requestId);
$ok(($result['status']??0)===200&&($result['body']['state']??'')==='committed'&&($result['body']['result']['order_code']??'')===($submitted['order_code']??''),'PUBLIC_OWNER_SEES_CANONICAL_RECEIPT');
$other=$edge->result(['installation_id'=>$installation,'projection_id'=>'guest:'.str_repeat('f',32),'capabilities'=>[]],$requestId);
$ok(($other['status']??0)===403,'OTHER_GUEST_CANNOT_READ_RECEIPT');
$terminalRetry=$edge->enqueueGuest($installation,$envelope($payload,$requestId,time()+3));
$ok(($terminalRetry['status']??0)===200&&($terminalRetry['body']['state']??'')==='committed','TERMINAL_GUEST_RETRY_NO_SECOND_COMMAND');
$c=$localDb->prepare('SELECT id,status FROM orders WHERE client_token=?');$c->execute([$client]);$orders=$c->fetchAll();
$ok(count($orders)===1&&($orders[0]['status']??'')==='pending_approval','LOCAL_ORDER_STORED_EXACTLY_ONCE');
$localOrderId=(int)$orders[0]['id'];
$balance=function()use($localDb,$fixture):int{$s=$localDb->prepare('SELECT quantity_base FROM inventory_balances WHERE inventory_item_id=?');$s->execute([(int)$fixture['inventory']]);return (int)$s->fetchColumn();};
$before=$balance();$ok($before===99952,'NO_EXTRA_STOCK_DEBIT_BEFORE_STAFF_APPROVAL'); // prior R225 fixture had -48
$admin=['id'=>(int)$fixture['admin_id'],'role'=>'admin'];
$approved=$local->orderStaffActions()->changeStatus(['order_id'=>$localOrderId,'status'=>'accounted'],$admin);
$ok(($approved['status']??'')==='accounted','LOCAL_STAFF_APPROVES_BRIDGED_ORDER');
$again=$local->orderStaffActions()->changeStatus(['order_id'=>$localOrderId,'status'=>'accounted'],$admin);
$ok(($again['idempotent']??false)===true,'STAFF_APPROVAL_BRIDGED_ORDER_DEDUP');
$ok($balance()===$before-48,'BRIDGED_ORDER_STOCK_DEBIT_EXACTLY_ONCE');
$mov=$localDb->prepare("SELECT quantity_base,total_cost_delta FROM inventory_movements m JOIN order_items oi ON oi.id=m.source_id WHERE m.source_type='order_item' AND oi.order_id=? ORDER BY m.id");$mov->execute([$localOrderId]);$movement=$mov->fetchAll();
$ok(count($movement)===2&&array_map('intval',array_column($movement,'quantity_base'))===[-40,-8],'BRIDGED_BUNDLE_BOTH_CHILD_MOVEMENTS');
$ok(array_sum(array_map('intval',array_column($movement,'total_cost_delta')))===-144,'BRIDGED_HISTORICAL_MATERIAL_COST');
$replayed=$edge->enqueueGuest($installation,$envelope($payload,$requestId,time()+4));
$ok(($replayed['body']['deduplicated']??false)===true&&$balance()===$before-48,'AFTER_ACCOUNTING_REPLAY_HAS_NO_SIDE_EFFECT');
// A never-claimed expired request cannot be dispatched to Local.
$expiredClient='r227-ci-expired-client-00000001';$expiredPayload=$payload;$expiredPayload['client_token']=$expiredClient;
$oldId='guest-order-submit:'.substr(hash('sha256','r227-expired'),0,56);
$expired=$edge->enqueueGuest($installation,$envelope($expiredPayload,$oldId,time()-500));
$ok(($expired['status']??0)===202,'EXPIRED_COMMAND_ENQUEUED_BEFORE_CLAIM');
$empty=$edge->claim($installation,20,0);
$ok(($empty['status']??0)===404,'EXPIRED_COMMAND_NOT_CLAIMED');
$expiredState=$edge->result($ownerSession,$oldId);
$ok(($expiredState['status']??0)===200&&($expiredState['body']['state']??'')==='expired','EXPIRED_RESULT_VISIBLE_NO_LOCAL_MUTATION');
$c->execute([$expiredClient]);$ok(count($c->fetchAll())===0,'EXPIRED_COMMAND_CREATED_NO_LOCAL_ORDER');
$remaining=(int)$pubDb->query("SELECT COUNT(*) FROM realtime_requests WHERE state IN('queued','claimed')")->fetchColumn();
$ok($remaining===0,'PUBLIC_NO_UNRESOLVED_COMMANDS');
$ok(!$pubDb->inTransaction()&&!$localDb->inTransaction(),'BOTH_DATABASE_TRANSACTIONS_CLOSED');
echo 'PASS_R227_PUBLIC_QUEUE_LOCAL_DISPATCH_ACK_AND_INVENTORY_'.$testCount."_CHECKS\n";